  <button id="showBtn">뜻 보기</button>
  <button id="nextBtn">다음</button>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var words, i, means;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("showBtn").addEventListener('click', function () {
      __show("meaning", "show");
    });
    document.getElementById("nextBtn").addEventListener('click', function () {
      i = mathRandomInt(1, 3);
      document.getElementById("word").textContent = words[(i - 1)];
      document.getElementById("meaning").textContent = means[(i - 1)];
      __show("meaning", "hide");
    });

    words = ['apple', 'dog', 'book'];
    means = ['사과', '개', '책'];
    __show("meaning", "hide");
  </script>
</body>
