    #clock { font-size: 72px; font-family: monospace; margin: 16px; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>⏱️ 10초 딱 맞추기</h1>
  <p>시작하고 마음속으로 세다가 10.00초에 멈춰요! (3초 뒤엔 시간이 숨겨져요)</p>
  <div id="clock">0.00</div>
  <button id="go">시작</button>
  <p id="msg"></p>
  <p>최고 기록(차이): <span id="best">-</span></p>
  <script>
    const clock = document.getElementById('clock');
    const goBtn = document.getElementById('go');
    const msg = document.getElementById('msg');
    let running = false;
    let startTime = 0;
    let result = 0;
    let best = null;
    let timer = null;

    function elapsed() {
      return (performance.now() - startTime) / 1000;
    }

    function update() {
      if (!running) return;
      const t = elapsed();
      clock.textContent = t < 3 ? t.toFixed(2) : '?.??';
    }

    goBtn.addEventListener('click', function () {
      if (!running) {
        running = true;
        startTime = performance.now();
        msg.textContent = '';
        goBtn.textContent = '멈춰!';
        clearInterval(timer);
        timer = setInterval(update, 30);
        update();
        return;
      }
      running = false;
      clearInterval(timer);
      result = elapsed();
      clock.textContent = result.toFixed(2);
      const diff = Math.abs(result - 10);
      if (diff < 0.1) msg.textContent = '🎯 완벽해요! 차이 ' + diff.toFixed(2) + '초';
      else if (diff < 0.5) msg.textContent = '👍 아깝다! 차이 ' + diff.toFixed(2) + '초';
      else msg.textContent = (result < 10 ? '너무 빨라요' : '너무 늦어요') + ' (차이 ' + diff.toFixed(2) + '초)';
      if (best === null || diff < best) {
        best = diff;
        document.getElementById('best').textContent = best.toFixed(2) + '초';
      }
      goBtn.textContent = '다시 도전';
    });
  </script>
</body>
</html>
