  </style>
</head>
<body>
  <h1 id="timeText">30</h1>
  <button id="startBtn">시작</button>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __size(name, prop, v) {
      var s = $(name).style;
      if (prop === 'opacity') s.opacity = v / 100;
      else if (prop === 'rotate') s.transform = 'rotate(' + v + 'deg)';
      else s[prop] = v + 'px';
    }
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var left, running;

    document.getElementById("startBtn").addEventListener('click', function () {
      if (left > 0) {
        running = true;
      }
    });
    __timers.push(setInterval(function () {
      if (running) {
        left = (typeof left === 'number' ? left : 0) + -1;
        document.getElementById("timeText").textContent = left;
        if (left <= 10) {
          document.getElementById("timeText").style.color = "#ef4444";
        }
        if (left <= 0) {
          running = false;
          document.getElementById("timeText").textContent = '끝!';
          __beep(440.00, 1);
        }
      }
    }, 1000));

    left = 30;
    running = false;
    __size("timeText", "fontSize", 80);
  </script>
</body>
</html>
