        r = String(w.charAt((i - 1))) + String(r);
      }
      document.getElementById("out").textContent = r;
      if (r == w && !!w.length) {
        document.getElementById("pal").textContent = 'Palindrome!';
      } else {
        document.getElementById("pal").textContent = '';
