<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>두더지 잡기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #dcfce7; color: #1f2937; padding: 24px; }
    #board { display: grid; grid-template-columns: repeat(3, 100px); gap: 10px; justify-content: center; margin: 16px auto; }
    .hole { width: 100px; height: 100px; font-size: 56px; border: none; border-radius: 50%; background: #78350f; cursor: pointer; }
    .hole.up { background: #a16207; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🔨 두더지 잡기 (30초)</h1>
  <p>점수: <span id="score">0</span> · 남은 시간: <span id="time">30</span>초</p>
  <div id="board"></div>
  <p id="msg">시작을 누르고 두더지를 클릭하세요!</p>
  <button id="start">시작</button>
  <script>
    const board = document.getElementById('board');
    const msg = document.getElementById('msg');
    const startBtn = document.getElementById('start');
    const holes = [];
    let mole = -1;        // 두더지가 있는 구멍 번호 (-1이면 없음)
    let score = 0;
    let timeLeft = 30;
    let running = false;
    let moleTimer = null;
    let clockTimer = null;

    for (let i = 0; i < 9; i++) {
      const h = document.createElement('button');
      h.className = 'hole';
      h.addEventListener('click', function () { whack(i); });
      board.appendChild(h);
      holes.push(h);
    }

    function draw() {
      holes.forEach(function (h, i) {
        h.textContent = i === mole ? '🐹' : '';
        h.classList.toggle('up', i === mole);
      });
    }

    function showMole() {
      if (!running) return;
      let next = Math.floor(Math.random() * 9);
      if (next === mole) next = (next + 1) % 9;
      mole = next;
      draw();
    }

    function whack(i) {
      if (!running || i !== mole) return;
      score += 1;
      document.getElementById('score').textContent = score;
      mole = -1; // 한 번 잡은 두더지는 사라져요
      draw();
    }

    function tickClock() {
      if (!running) return;
      timeLeft -= 1;
      document.getElementById('time').textContent = timeLeft;
      if (timeLeft <= 0) endGame();
    }

    function startGame() {
      clearInterval(moleTimer);
      clearInterval(clockTimer);
      score = 0;
      timeLeft = 30;
      mole = -1;
      running = true;
      document.getElementById('score').textContent = 0;
      document.getElementById('time').textContent = 30;
      msg.textContent = '';
      startBtn.textContent = '다시 시작';
      draw();
      moleTimer = setInterval(showMole, 800);
      clockTimer = setInterval(tickClock, 1000);
    }

    function endGame() {
      running = false;
      clearInterval(moleTimer);
      clearInterval(clockTimer);
      timeLeft = 0;
      document.getElementById('time').textContent = 0;
      mole = -1;
      draw();
      msg.textContent = '⏰ 게임 끝! 잡은 두더지: ' + score + '마리';
    }

    startBtn.addEventListener('click', startGame);
  </script>
</body>
</html>
