<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>산성비 타자</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #f0fdfa; color: #1f2937; padding: 24px; }
    canvas { background: #134e4a; border-radius: 8px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    input { font-size: 22px; padding: 8px; margin: 4px; width: 220px; text-align: center; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>☔ 산성비 타자 게임</h1>
  <p>점수: <span id="score">0</span> · 목숨: <span id="lives">5</span></p>
  <canvas id="game" width="480" height="360"></canvas>
  <div><input id="typing" placeholder="단어 입력 후 엔터" disabled></div>
  <p id="msg">떨어지는 단어가 바닥에 닿기 전에 쳐서 없애요!</p>
  <button id="start">시작</button>
  <script>
    const WORDS = ['나무', '구름', '토끼', '바람', '기차', '모자', '우유', '사탕', '별빛', '노래', '연못', '거북이', '햄버거', '수박', '달팽이'];
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const input = document.getElementById('typing');
    const msg = document.getElementById('msg');
    let drops = [];   // { text, x, y, speed }
    let score = 0;
    let lives = 5;
    let frame = 0;
    let running = false;
    let timer = null;

    function updateInfo() {
      document.getElementById('score').textContent = score;
      document.getElementById('lives').textContent = lives;
    }

    function startGame() {
      clearInterval(timer);
      drops = [];
      score = 0;
      lives = 5;
      frame = 0;
      running = true;
      input.disabled = false;
      input.value = '';
      input.focus();
      msg.textContent = '';
      document.getElementById('start').textContent = '다시 시작';
      updateInfo();
      timer = setInterval(tick, 30);
    }

    function gameOver() {
      running = false;
      clearInterval(timer);
      timer = null;
      input.disabled = true;
      msg.textContent = '💥 게임 오버! 점수: ' + score;
    }

    function tick() {
      if (!running) return;
      frame += 1;
      if (frame % Math.max(25, 70 - score) === 1) {
        drops.push({ text: WORDS[Math.floor(Math.random() * WORDS.length)], x: 20 + Math.random() * (W - 100), y: 0, speed: 0.8 + Math.random() * 0.6 });
      }
      for (let i = drops.length - 1; i >= 0; i--) {
        drops[i].y += drops[i].speed;
        if (drops[i].y > H) {
          drops.splice(i, 1);    // 바닥에 닿은 단어는 사라지고 목숨 -1
          lives = Math.max(0, lives - 1);
          updateInfo();
          if (lives === 0) {
            gameOver();
            break;
          }
        }
      }
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = '#ccfbf1';
      ctx.font = '22px sans-serif';
      for (const d of drops) ctx.fillText(d.text, d.x, d.y);
      ctx.fillStyle = '#f87171';
      ctx.fillRect(0, H - 4, W, 4);
    }

    input.addEventListener('keydown', function (e) {
      if (e.key !== 'Enter' || !running) return;
      const typed = input.value.trim();
      // 같은 단어 중 가장 아래(급한) 것부터 없애요
      let best = -1;
      drops.forEach(function (d, i) {
        if (d.text === typed && (best === -1 || d.y > drops[best].y)) best = i;
      });
      if (best !== -1) {
        drops.splice(best, 1);
        score += 10;
        updateInfo();
      }
      input.value = '';
    });
    document.getElementById('start').addEventListener('click', startGame);
    draw();
  </script>
</body>
</html>
