<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>과일 받기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #fff1f2; color: #1f2937; padding: 24px; }
    canvas { background: #f0fdf4; border: 3px solid #e11d48; border-radius: 8px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🧺 과일 받기</h1>
  <p>점수: <span id="score">0</span> · 목숨: <span id="lives">3</span></p>
  <canvas id="game" width="400" height="420"></canvas>
  <p id="msg">← → 키로 바구니를 움직여 과일을 받아요. 놓치거나 💣를 받으면 목숨 -1</p>
  <button id="start">시작</button>
  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const FRUITS = ['🍎', '🍌', '🍇', '🍓', '🍊'];
    const msg = document.getElementById('msg');
    const startBtn = document.getElementById('start');

    let basket = { x: 160, y: 380, w: 80, h: 30 };
    let items = [];   // { x, y, w, h, speed, emoji, bomb }
    let keys = {};
    let score = 0;
    let lives = 3;
    let running = false;
    let timer = null;

    function overlap(a, b) {
      return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
    }

    function updateInfo() {
      document.getElementById('score').textContent = score;
      document.getElementById('lives').textContent = lives;
    }

    function startGame() {
      clearInterval(timer);
      basket.x = 160;
      items = [];
      keys = {};
      score = 0;
      lives = 3;
      running = true;
      msg.textContent = '';
      startBtn.textContent = '다시 시작';
      updateInfo();
      timer = setInterval(tick, 20);
    }

    function loseLife() {
      lives = Math.max(0, lives - 1);
      updateInfo();
      if (lives === 0) {
        running = false;
        clearInterval(timer);
        timer = null;
        msg.textContent = '💥 게임 오버! 점수: ' + score;
      }
    }

    function tick() {
      if (!running) return;
      if (keys.ArrowLeft) basket.x = Math.max(0, basket.x - 7);
      if (keys.ArrowRight) basket.x = Math.min(W - basket.w, basket.x + 7);

      if (Math.random() < 0.03) {
        const bomb = Math.random() < 0.2;
        items.push({
          x: Math.random() * (W - 30), y: -30, w: 30, h: 30, speed: 2 + Math.random() * 2,
          bomb: bomb, emoji: bomb ? '💣' : FRUITS[Math.floor(Math.random() * FRUITS.length)]
        });
      }

      // 받았거나 바닥에 떨어진 건 바로 없애서 한 번만 계산돼요
      for (let i = items.length - 1; i >= 0; i--) {
        const it = items[i];
        it.y += it.speed;
        if (overlap(it, basket)) {
          items.splice(i, 1);
          if (it.bomb) {
            loseLife();
          } else {
            score += 1;
            updateInfo();
          }
        } else if (it.y > H) {
          items.splice(i, 1);
          if (!it.bomb) loseLife(); // 과일을 놓치면 목숨 -1
        }
        if (!running) return;
      }
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      ctx.font = '28px sans-serif';
      ctx.textBaseline = 'top';
      items.forEach(function (it) { ctx.fillText(it.emoji, it.x, it.y); });
      ctx.fillStyle = '#a16207';
      ctx.fillRect(basket.x, basket.y, basket.w, basket.h);
    }

    document.addEventListener('keydown', function (e) {
      if (e.key.startsWith('Arrow') || e.key === ' ') e.preventDefault();
      keys[e.key] = true;
    });
    document.addEventListener('keyup', function (e) {
      keys[e.key] = false;
    });
    startBtn.addEventListener('click', startGame);
    draw();
  </script>
</body>
</html>
