  <script>
    const faces = ['⚀', '⚁', '⚂', '⚃', '⚄', '⚅'];
    const rollBtn = document.getElementById('roll');
    let d1 = 1, d2 = 1;
    let rolling = false;
    let history = [];

    function randomDie() {
      return Math.floor(Math.random() * 6) + 1;
    }

    function show() {
      document.getElementById('d1').textContent = faces[d1 - 1];
      document.getElementById('d2').textContent = faces[d2 - 1];
    }

    rollBtn.addEventListener('click', function () {
      if (rolling) return;
      rolling = true;
      rollBtn.disabled = true;
      let count = 0;
      // 데굴데굴 굴러가는 것처럼 10번 바꾼 다음 멈춰요
      const timer = setInterval(function () {
        d1 = randomDie();
        d2 = randomDie();
        show();
        count += 1;
        if (count >= 10) {
          clearInterval(timer);
          rolling = false;
          rollBtn.disabled = false;
          const sum = d1 + d2;
          let text = '합계: ' + sum;
          if (d1 === d2) text += ' 🎉 더블!';
          document.getElementById('sum').textContent = text;
          history.unshift(sum);
          history = history.slice(0, 5);
          document.getElementById('history').textContent = history.join(', ');
        }
      }, 60);
    });
  </script>
