    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var prev, n;

    document.addEventListener('keydown', function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        if (document.getElementById("w").value.charAt(0) == prev.slice(-1)) {
          prev = document.getElementById("w").value;
          __add("list", prev);
          document.getElementById("last").textContent = prev;
          n = (typeof n === 'number' ? n : 0) + 1;
          document.getElementById("cnt").textContent = ['이어간 단어: ',n,'개'].join('');
        } else {
          alert('땡! 😝');
        }
        document.getElementById("w").value = '';
