    let running = false;
    let timer = null;

    function resetBall(toRight) {
      ball.x = W / 2;
      ball.y = H / 2;
      ball.dx = toRight ? 4 : -4;
      ball.dy = Math.random() < 0.5 ? -2 : 2;
    }

    function hitRect(c, r) {
      const nx = Math.max(r.x, Math.min(c.x, r.x + r.w));
      const ny = Math.max(r.y, Math.min(c.y, r.y + r.h));
      return Math.hypot(c.x - nx, c.y - ny) < c.r;
    }

    function showScore() {
      document.getElementById('board').textContent = '나 ' + myScore + ' : ' + comScore + ' 컴퓨터';
    }

    function startGame() {
      clearInterval(timer);
      me.y = 130;
      com.y = 130;
      myScore = 0;
      comScore = 0;
      keys = {};
      resetBall(true);
      running = true;
      msg.textContent = '';
      startBtn.textContent = '다시 시작';
      showScore();
      timer = setInterval(tick, 16);
    }

    function point(mine) {
      if (mine) myScore += 1; else comScore += 1;
      showScore();
      if (myScore >= WIN || comScore >= WIN) {
        running = false;
        clearInterval(timer);
        timer = null;
        msg.textContent = myScore >= WIN ? '🏆 내가 이겼어요!' : '💥 게임 오버! 컴퓨터 승리';
        return;
      }
      resetBall(!mine);
    }

    function tick() {
      if (!running) return;
      // 위/아래 키는 y만 바꿔요
      if (keys.ArrowUp) me.y = Math.max(0, me.y - 6);
      if (keys.ArrowDown) me.y = Math.min(H - me.h, me.y + 6);
      // 컴퓨터는 공을 따라가지만 최대 속도가 있어요
      const target = ball.y - com.h / 2;
      com.y += Math.max(-3.5, Math.min(3.5, target - com.y));
      com.y = Math.max(0, Math.min(H - com.h, com.y));

      ball.x += ball.dx;
      ball.y += ball.dy;
      if (ball.y < ball.r) { ball.y = ball.r; ball.dy = Math.abs(ball.dy); }
      if (ball.y > H - ball.r) { ball.y = H - ball.r; ball.dy = -Math.abs(ball.dy); }

      if (ball.dx < 0 && hitRect(ball, me)) {
        ball.dx = Math.abs(ball.dx) + 0.3;
        ball.dy = (ball.y - (me.y + me.h / 2)) / 8;
      }
      if (ball.dx > 0 && hitRect(ball, com)) {
        ball.dx = -(Math.abs(ball.dx) + 0.3);
        ball.dy = (ball.y - (com.y + com.h / 2)) / 8;
      }

      if (ball.x < -ball.r) point(false);
      else if (ball.x > W + ball.r) point(true);
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = '#f8fafc';
      for (let y = 0; y < H; y += 20) ctx.fillRect(W / 2 - 1, y, 2, 10);
      ctx.fillRect(me.x, me.y, me.w, me.h);
      ctx.fillRect(com.x, com.y, com.w, com.h);
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
      ctx.fill();
    }

    document.addEventListener('keydown', function (e) {
      if (e.key.startsWith('Arrow') || e.key === ' ') e.preventDefault();
      keys[e.key] = true;
    });
    document.addEventListener('keyup', function (e) {
      keys[e.key] = false;
    });
    startBtn.addEventListener('click', startGame);
    draw();
  </script>
</body>
</html>
