  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var qs, answers, score, i, right;

    // 이 함수를 설명하세요...
    function showQuestion() {
      if (i > qs.length) {
        __show("quizBox", "hide");
        document.getElementById("final").textContent = ['끝! 점수: ',score,' / ',qs.length].join('');
      } else {
        document.getElementById("question").textContent = qs[(i - 1)];
        right = answers[(i - 1)];
        document.getElementById("answer").value = '';
      }
    }

    document.getElementById("check").addEventListener('click', function () {
      if (document.getElementById("answer").value.trim() == right) {
        score = (typeof score === 'number' ? score : 0) + 1;
        document.getElementById("msg").textContent = '정답! ⭕';
        document.getElementById("msg").style.color = "#22c55e";
        __beep(523.25, 0.2);
      } else {
        document.getElementById("msg").textContent = '땡! 정답: ' + String(right);
        document.getElementById("msg").style.color = "#ef4444";
        __beep(261.63, 0.3);
      }
      document.getElementById("score").textContent = '점수: ' + String(score);
      i = (typeof i === 'number' ? i : 0) + 1;
      showQuestion();
    });
    document.getElementById("hintBtn").addEventListener('click', function () {
      document.getElementById("msg").textContent = '첫 글자: ' + String(right.charAt(0));
