      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var en, right, ko, i, score;

    document.getElementById("checkBtn").addEventListener('click', function () {
      right = ko[(i - 1)];
      if (document.getElementById("ansBox").value.trim() == right) {
        score = (typeof score === 'number' ? score : 0) + 1;
        document.getElementById("msg").textContent = '정답!';
      } else {
        document.getElementById("msg").textContent = '정답은 ' + String(right);
      }
      i = (typeof i === 'number' ? i : 0) + 1;
      document.getElementById("ansBox").value = '';
      if (i > 3) {
        document.getElementById("word").textContent = ['점수: ',score,' / 3'].join('');
        __show("row1", "hide");
      } else {
        document.getElementById("word").textContent = en[(i - 1)];
      }
    });

    en = ['apple', 'dog', 'book'];
    ko = ['사과', '개', '책'];
    i = 1;
    score = 0;
  </script>
</body>
