  <button id="checkBtn">Check</button>
  <h2 id="result"></h2>
  <button id="resetBtn">New game</button>
  <script>
    var answer, tries;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("checkBtn").addEventListener('click', function () {
      tries = (typeof tries === 'number' ? tries : 0) + 1;
      if ((parseFloat(document.getElementById("guessIn").value) || 0) == answer) {
        document.getElementById("result").textContent = 'Correct! Tries: ' + String(tries);
      } else if ((parseFloat(document.getElementById("guessIn").value) || 0) < answer) {
        document.getElementById("result").textContent = 'Higher ⬆';
      } else {
        document.getElementById("result").textContent = 'Lower ⬇';
      }
    });
    document.getElementById("resetBtn").addEventListener('click', function () {
      answer = mathRandomInt(1, 100);
      tries = 0;
      document.getElementById("result").textContent = '';
      document.getElementById("guessIn").value = '';
    });

    answer = mathRandomInt(1, 100);
    tries = 0;
